'use strict';
function newLocalId(){if(window.crypto?.randomUUID)return crypto.randomUUID();const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('')}
const cloud={me:null,version:0,linked:[],familyUsers:[],communities:[],requests:[],messages:[],activities:[],ready:false,busy:false,dirty:false,error:'',saveTimer:null,activeElder:null};
const defaultExtra={medications:[],appointments:[],jobApplications:[],contacts:[],studyProgress:{},communityNotes:[],checkins:[],quizAnswers:{},achievements:[],completedCourses:[]};
state={...structuredClone(defaultExtra),...state};
let pendingAudio='',voiceRecorder=null,voiceStream=null,voiceChunks=[],recordStarted=0,recordLimit=null;
function imgPath(p){return /^(\/|data:|https:)/.test(p||'')?p:'assets/'+(p||'community.webp')}
function note(t){return `<p class="small-note">${t}</p>`}
function linkButton(p,t,c='primary',id=''){return `<button class="${c}" data-action="x-go" data-page="${p}" data-id="${esc(id)}">${t}</button>`}
function selectInput(name,label,opts){return `<label class="form-group"><span>${label}</span><select name="${name}">${opts.map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('')}</select></label>`}
function textArea(name,label,required=true){return `<label class="form-group"><span>${label}</span><textarea name="${name}" ${required?'required':''} maxlength="1500"></textarea></label>`}
function newForm(id,body,submit='保存'){return `<form id="x-${id}">${body}<div class="inline-error" role="alert"></div><button class="primary" type="submit">${submit}</button></form>`}
function command(a,t,c='primary',attrs=''){return action('x-'+a,t,c,attrs)}
function controls(){return `${command('refresh','刷新云端','text-btn')} ${linkButton('account','账号与同步','text-btn')}`}
function syncStatus(){if(!cloud.ready)return '正在连接';if(!cloud.me)return '访客模式 · 数据仅在本机';if(cloud.error)return cloud.error;return cloud.busy?'正在同步…':cloud.dirty?'有待同步记录':'已登录 · 云端记录'}
function markStatus(){const e=$('#sync-state');if(e)e.textContent=syncStatus();const foot=$('.home-footnote');if(foot)foot.textContent=cloud.me?'个人记录按账号保存 · 家庭数据需授权':'访客体验 · 记录仅在当前浏览器'}
async function api(op,data={}){const r=await fetch('/api/service',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op,...data})});const b=await r.json();if(!r.ok)throw new Error(b.error||'保存失败，请稍后重试');return b}
function snapshot(){const v={...state};delete v.communitySession;return structuredClone(v)}
window.queueCloudSave=()=>{if(!cloud.ready||!cloud.me||window.loadingCloud)return;cloud.dirty=true;clearTimeout(cloud.saveTimer);cloud.saveTimer=setTimeout(saveCloud,650);markStatus()};
async function saveCloud(){if(!cloud.me||cloud.busy||!cloud.dirty)return;cloud.busy=true;cloud.dirty=false;cloud.error='';markStatus();try{const r=await api('save',{state:snapshot(),version:cloud.version});cloud.version=r.version}catch(e){cloud.dirty=true;cloud.error=e.message;toast(e.message)}finally{cloud.busy=false;markStatus();if(cloud.dirty&&!cloud.error)window.queueCloudSave()}}
async function refreshCloud(first=false){if(cloud.busy)throw new Error('正在同步，请稍后');if(!first&&cloud.dirty){await saveCloud();if(cloud.dirty)throw new Error('本机有尚未同步的记录，请先导出备份，避免覆盖。')}
 const r=await fetch('/api/service',{cache:'no-store'});const b=await r.json();if(!r.ok)throw new Error(b.error||'云端暂不可用');window.loadingCloud=true;
 cloud.me=b.me;cloud.version=b.version||0;cloud.linked=b.linked||[];cloud.familyUsers=b.familyUsers||[];cloud.communities=b.communities||[];cloud.requests=b.requests||[];cloud.messages=b.messages||[];cloud.activities=b.activities||[];
 if(b.me){const prefs={role:state.role,font:state.font,voice:state.voice,contrast:state.contrast};window.dataStorageKey='yilu-account-'+b.me.id;state={...structuredClone(initial),...structuredClone(defaultExtra),...(b.document||{}),...prefs};state.profile=b.me.name==='新用户'?(b.document?.profile||'我的档案'):b.me.name;state.communitySession=cloud.communities.length>0;state.joined=[...new Set([...(state.joined||[]),...(b.joined||[])])];localStorage.setItem(window.dataStorageKey,JSON.stringify(state))}
 cloud.ready=true;window.loadingCloud=false;cloud.error='';render(true);markStatus();}
const oldRenderFull=render;render=function(keep=false){oldRenderFull(keep);if(!$('#sync-state')){const b=document.createElement('div');b.className='sync-status';b.id='sync-state';b.setAttribute('role','status');$('.app-header').after(b)}markStatus()};
metrics=()=>{const last=k=>state.records.slice().reverse().find(r=>r[k]!==undefined&&r[k]!=='')?.[k];return {bp:last('sys')?`${last('sys')}/${last('dia')}`:'—',heart:last('heart')||'—',sleep:last('sleep')??'—',steps:'—',sample:false}};
const oldActivityAll=activityAll;activityAll=()=>[...cloud.activities.filter(a=>a.kind!=='article').map(a=>({...a,people:Math.max(0,(a.registered||0)-(state.joined.includes(a.id)?1:0))})),...oldActivityAll().filter(a=>a.kind!=='article')];
const oldActivityCard=activityCard;activityCard=a=>oldActivityCard(a).replaceAll('assets/'+(a.image||'community.webp'),imgPath(a.image));
const oldElderHome=elderHome;elderHome=()=>oldElderHome().replace(/src="assets\/(\/api[^\"]*)"/g,'src="$1"')+linkButton('intake','五维需求评估与服务匹配','secondary');
const oldFamilyHome=familyHome;familyHome=()=>`<div class="page-heading"><h2>家属关怀</h2><p>查看已授权的长辈，协助记录服务需求。</p></div>${cloud.me?cloud.linked.length?cloud.linked.map(l=>`<div class="card"><h3>${esc(l.name)}</h3><p>${l.records.length} 条健康记录 · 小颐成长值 ${l.xp}</p>${command('view-elder','查看健康周报','primary',`data-id="${l.elder}"`)}</div>`).join('')+linkButton('account','连接另一位长辈','secondary'):empty('还没有获得长辈授权。请让长辈在“隐私与授权”生成邀请码。','shield')+linkButton('account','输入长辈邀请码','primary'):oldFamilyHome()}${section('家庭服务')}${linkButton('resources','代长辈申请服务','secondary')}${linkButton('inbox','家人留言与社区回复','secondary')}`;
const oldCommunity=communityHome;communityHome=()=>`<div class="page-heading"><h2>社区工作台</h2><p>发布活动、处理申请、回复留言。</p></div>${cloud.me?cloud.communities.length?`<div class="card"><h3>${esc(cloud.communities[0].name)}</h3><p>服务码 <b>${esc(cloud.communities[0].code)}</b></p>${note('将服务码提供给长者，申请才会发送到您的工作空间。')}</div>`+`<div class="stat-grid"><div class="stat-card"><label>待办申请</label><strong class="stat-num">${cloud.requests.filter(r=>r.stage<7&&cloud.communities.some(c=>c.id===r.community)).length}</strong></div><div class="stat-card"><label>社区活动</label><strong class="stat-num">${cloud.activities.filter(a=>cloud.communities.some(c=>c.id===a.community)).length}</strong></div></div>`:empty('还没有加入社区工作空间。','community'):note('访客可体验页面；社区业务数据需要登录并加入工作空间。')}${linkButton('workspace','社区与成员管理','secondary')}${linkButton('requests','需求处理工作台','secondary')}${command('publish','发布社区活动','primary')}${linkButton('inbox','留言与回复','secondary')}${linkButton('science','健康科普文章库','secondary')}`;
communityGate=()=>go('workspace');
function linkedElder(){return cloud.linked.find(l=>l.elder===cloud.activeElder)||cloud.linked[0]}
function readableRecords(){return state.role==='family'&&cloud.me?(linkedElder()?.records||[]):state.records}
const oldHealth=healthPage;healthPage=()=>{if(state.role==='family'&&cloud.me){const l=linkedElder();if(!l)return privacyPage();return heading(esc(l.name)+'的健康记录','由长辈单独授权')+healthDashboard(l.records,false)+linkButton('weekly','查看健康周报','secondary')}return heading('我的健康','血压、血糖、睡眠与用药记录',false)+`<div class="row between"><span class="badge">${state.records.length} 条手动记录</span>${command('record','添加记录','text-btn')}</div>`+healthDashboard(state.records,true)+`<div class="card">${wide('meds','pill','用药管理','添加药品、服药打卡')}${wide('weekly','clipboard','健康趋势与周报','根据实际记录生成')}${wide('consult','doctor','就医与预约','科室指引、预约意向')}${wide('watch','watch','颐安手环','三档方案、接入状态')}</div>`}
function healthDashboard(records,own){const last=k=>records.slice().reverse().find(x=>x[k]!==undefined&&x[k]!=='')?.[k];const r=Object.fromEntries(['sys','dia','glucose','glucoseType','heart','sleep'].map(k=>[k,last(k)]));return `<div class="stat-grid">${[['血压',r.sys?`${r.sys}/${r.dia}`:'未记录','mmHg'],['血糖',r.glucose||'未记录','mmol/L · '+(r.glucoseType||'空腹')],['睡眠',r.sleep??'未记录','小时'],['心率',r.heart||'未记录','次/分']].map(([t,v,unit])=>`<div class="stat-card"><label>${t}</label><strong class="stat-num">${esc(v)}</strong><small>${esc(unit)}</small></div>`).join('')}</div>${section('最近的记录')}${records.length?records.slice(-10).reverse().map(r=>`<div class="card"><h3>${esc(r.date)}</h3><p>${[r.sys?`血压 ${r.sys}/${r.dia} mmHg`:'',r.glucose?`血糖 ${r.glucose} mmol/L（${esc(r.glucoseType)}）`:'',r.heart?`心率 ${r.heart} 次/分`:'',r.sleep!==undefined&&r.sleep!==''?`睡眠 ${r.sleep} 小时`:''].filter(Boolean).join(' · ')}</p>${r.note?`<p>${esc(r.note)}</p>`:''}</div>`).join(''):empty('暂无记录。添加真实测量值后，这里会显示变化。','heart')}`}
function recordDialog(){modal('添加健康记录',newForm('record',`<p class="small-note">可以只填一项。请按设备实测结果填写。</p>${optionalField('sys','收缩压（mmHg）','number','min="50" max="260"')}${optionalField('dia','舒张压（mmHg）','number','min="30" max="180"')}${optionalField('glucose','血糖（mmol/L）','number','min="0.5" max="40" step="0.1"')}${selectInput('glucoseType','测量时段',[['空腹','空腹'],['餐后2小时','餐后2小时'],['随机','随机']])}${optionalField('heart','心率（次/分）','number','min="25" max="250"')}${optionalField('sleep','睡眠（小时）','number','min="0" max="24" step="0.1"')}${textArea('note','备注',false)}`,'保存记录'))}
function optionalField(n,l,t='text',attrs=''){return `<label class="form-group"><span>${l}</span><input name="${n}" type="${t}" ${attrs}></label>`}
medPage=()=>heading('用药管理','按既有医嘱添加，不提供处方或剂量建议。')+command('add-med',icon('plus')+'添加药品','primary')+(state.medications.length?state.medications.map(m=>`<div class="card"><div class="row between"><h3>${esc(m.name)}</h3>${command('delete-med','停用','text-btn',`data-id="${m.id}"`)}</div><p>每次 ${esc(m.dose)} · ${esc(m.instructions||'按医嘱服用')}</p>${m.times.map(time=>{let key=today()+m.id+time;return `<div class="dose-row"><strong>${esc(time)}</strong>${command('dose',state.meds.includes(key)?'已服药 ✓':'记录已服','pill-button',`data-id="${m.id}" data-time="${time}"`)}</div>`}).join('')}</div>`).join(''):empty('还没有添加药品。请按本人医嘱填写药名、时间和用量。','pill'))+note('页面打开时可提示到时服药；网页关闭后不能后台推送。未确认是否已服药时，请先核对记录或咨询家属、药师。')+linkButton('consult','有用药问题？查看就医协助','secondary');
function medDialog(){modal('添加药品',newForm('med',field('name','药品名称','text','maxlength="80"')+field('times','服药时间（多个用逗号分隔）','text','placeholder="08:00,20:00" maxlength="80"')+field('dose','每次用量（以医嘱为准）','text','placeholder="例如：1片" maxlength="40"')+optionalField('instructions','服用说明','text','maxlength="160"'),'添加药品'))}
function realTrend(records,key,label,unit){const days=Array.from({length:7},(_,i)=>{const dt=new Date();dt.setDate(dt.getDate()-(6-i));return dt.toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'})});const values=days.map(date=>{const a=records.filter(r=>r.date===date&&Number(r[key])>0).map(r=>Number(r[key]));return a.length?a.reduce((s,v)=>s+v,0)/a.length:null});const present=values.filter(x=>x!==null);if(!present.length)return `<div class="card"><h3>${label}</h3>${empty('最近七天暂无记录')}</div>`;const max=Math.max(...present)*1.15||1;return `<div class="card"><h3>${label}</h3><div class="actual-chart" role="img" aria-label="${label}：${values.map((v,i)=>days[i]+(v===null?'无记录':v.toFixed(1))).join('，')}">${values.map((v,i)=>`<div><span>${v===null?'—':Number(v.toFixed(1))}</span><i style="height:${v===null?2:Math.max(5,v/max*90)}px" class="${v===null?'missing':''}"></i><small>${days[i].slice(5)}</small></div>`).join('')}</div><p>七天平均 ${Number((present.reduce((s,v)=>s+v,0)/present.length).toFixed(1))} ${unit}</p></div>`}
weeklyPage=()=>{if(state.role==='family'&&cloud.me&&!linkedElder())return privacyPage();if(state.role==='family'&&!cloud.me&&!state.shared)return privacyPage();const rs=readableRecords();return heading('健康周报','最近七天的实际记录，无记录的日期留空。')+realTrend(rs,'sys','收缩压','mmHg')+realTrend(rs,'glucose','血糖','mmol/L')+realTrend(rs,'sleep','睡眠','小时')+`<div class="card"><h3>记录情况</h3><p>共 ${rs.length} 条历史记录，最近七天 ${rs.filter(r=>new Date(r.date)>=new Date(Date.now()-7*86400000)).length} 条。</p></div>`+note('不同血糖测量时段可能影响可比性。图表只展示记录，不作医学分析。')};
