const oldPrivacy=privacyPage;privacyPage=()=>heading('隐私与家庭授权','健康数据由长辈授权，随时可撤回。')+(cloud.me?`<div class="card"><h3>邀请家属</h3><p>生成一次性邀请码，交给您同意查看健康记录的家属。家属登录自己的账号后输入该码。</p>${command('family-invite','生成家属邀请码','primary')}</div>${cloud.familyUsers.length?cloud.familyUsers.map(f=>`<div class="card"><h3>${esc(f.name)}</h3><p>${f.granted?'当前可以查看您的健康记录':'已撤回授权'}</p>${f.granted?command('revoke','撤回查看授权','secondary',`data-id="${f.family}"`):''}</div>`).join(''):note('目前还没有家属获得您的云端查看授权。')}${cloud.linked.length?`<div class="card"><h3>我获得的长辈授权</h3>${cloud.linked.map(l=>`<p>${esc(l.name)}</p>`).join('')}</div>`:''}${linkButton('account','输入长辈邀请码','secondary')}`:oldPrivacy())+`<div class="card"><h3>数据保存范围</h3><p>访客记录保存在本机；登录后个人记录保存在账号下。家属仅能在获得授权后查看健康记录。服务申请只发送给您选择的社区，其工作人员可以查看和处理该申请。</p><p>社区工作空间由创建者自行管理，不代表医疗机构或政府部门认证。</p>${command('export','导出我的记录','secondary')}</div>`;
