const oldProfile=profilePage;profilePage=()=>oldProfile().replace('网页体验版 · 本地记录<br>真实账号与机构服务尚未接入',cloud.me?'账号已登录 · 支持云端同步':'访客模式 · 可登录启用云端同步')+`<div class="card">${wide('account','user',cloud.me?'账号与云端同步':'登录与云端同步',syncStatus())}${wide('inbox','mail','家人及社区留言','文字、语音与回复')}${wide('appointments','doctor','我的就医安排','预约意向与就诊准备')}${wide('applications','briefcase','我的岗位意向','岗位申请记录')}${wide('intake','clipboard','五维需求评估','五个问题，匹配服务')}${wide('contacts','phone','家人与紧急联系人','拨号与求助')}${wide('workspace','community','社区工作空间','成员、服务码与权限')}</div>`;
function requestList(){if(state.role==='community')return cloud.me?cloud.requests.filter(r=>cloud.communities.some(c=>c.id===r.community)):state.requests;return [...cloud.requests.filter(r=>r.owner===cloud.me?.id||(state.role==='family'&&cloud.linked.some(l=>l.elder===r.owner))),...state.requests]}
requestsPage=()=>{const list=requestList().filter(r=>filter==='全部'||(filter==='待处理'?r.stage<7:r.stage===7));return heading(state.role==='community'?'社区申请':'我的服务申请','本机草稿与已发送到社区的申请分开标注。',false)+`<div class="tabs">${['全部','待处理','已完成'].map(t=>action('filter',t,filter===t?'selected':'',`data-value="${t}"`)).join('')}</div>`+(list.length?list.map(r=>`<button class="card request-card" data-action="x-request" data-id="${r.id}"><div class="row between"><span class="badge">${steps[r.stage]}</span><small>${r.community?'已发送社区':'本机流程体验'}</small></div><h3>${esc(r.title)}</h3><p>${esc(r.name)} · ${esc(r.date)}</p><p>${esc(r.need)}</p><span class="text-btn">查看详情 ›</span></button>`).join(''):empty('暂无服务申请。','clipboard'))+linkButton(state.role==='community'?'workspace':'resources',state.role==='community'?'管理社区工作空间':'查找服务','secondary')};
function findRequest(id){return cloud.requests.find(r=>r.id===id)||state.requests.find(r=>r.id===id)}
requestDetailPage=()=>{const r=findRequest(selected);if(!r)return heading('申请详情')+empty('未找到申请');const canManage=state.role==='community'&&(r.community?cloud.communities.some(c=>c.id===r.community):!cloud.me);return heading(esc(r.title),esc(r.communityName||'本机流程体验'))+`<div class="card"><p>申请人：${esc(r.name)}</p><p>${esc(r.need)}</p><p>联系时间：${esc(r.when)}</p>${r.provider?`<p>匹配资源：${esc(r.provider)}</p>`:''}</div><div class="steps">${steps.map((s,i)=>`<div class="step ${i<r.stage?'complete':i===r.stage?'current':''}"><h4>${s}</h4><p>${i<=r.stage?esc(r.log?.[i]||'已记录'):'等待前一步完成'}</p></div>`).join('')}</div>${canManage&&r.stage<7?command('advance','记录下一步：'+steps[r.stage+1],'primary',`data-id="${r.id}"`):''}${!canManage&&r.stage>=6?command('feedback','填写服务反馈','primary',`data-id="${r.id}"`):''}${r.feedback?`<div class="card"><h3>申请人反馈</h3><p>${esc(r.feedback)}</p></div>`:''}${note(r.community?'记录已在账号和所选社区间同步。转介处理记录由工作人员填写，不会自动呼叫或通知外部机构。':'此申请仅在当前浏览器演示，未发送到机构。')}`};
applyPage=()=>{const r=resourceData.find(r=>r.id===selected)||resourceData[0];return heading('发起服务申请','服务类别自动带入，无需重复填写。')+`<div class="card"><span class="badge">${r.dim} · ${r.cat}</span><h3>${r.title}</h3></div>`+newForm('apply',field('name','申请人称呼','text',`value="${esc(state.profile)}" maxlength="30"`)+textArea('need','您需要哪些帮助？')+selectInput('when','希望联系的时间',[['工作日上午','工作日上午'],['工作日下午','工作日下午'],['由家属协助联系','由家属协助联系']])+(cloud.me?`${state.role==='family'?selectInput('elder','为谁申请',[[cloud.me.id,'为我自己'],...cloud.linked.map(l=>[l.elder,l.name])]):''}${optionalField('communityCode','社区服务码（填写后发送给该社区）','text','maxlength="50" placeholder="向社区工作人员索取"')}`:'')+`<label class="consent"><input type="checkbox" name="consent" required><span>${cloud.me?'我同意将本次申请信息发送给所选社区；未填服务码则只保存本机。':'我同意在本机保存本次体验申请。'}</span></label>`,'确认提交')};
const oldActivityDetail=activityDetailPage;activityDetailPage=()=>{const a=activityAll().find(a=>a.id===selected)||activityData[0];return oldActivityDetail().replaceAll('assets/'+(a.image||'community.webp'),imgPath(a.image)).replace(/<div class="demo-banner">体验活动[\s\S]*?<\/div>/,a.cloud?note('由 '+esc(a.communityName)+' 发布。报名信息会发送到该社区；具体活动安排请向发布方核实。'):note('样例活动仅用于体验。社区发布的活动会标注发布方。'))};
function publishDialog(kind='activity'){if(cloud.me&&!cloud.communities.length){go('workspace');return}modal(kind==='article'?'发布健康科普':'发布社区活动',newForm('publish',`<input type="hidden" name="kind" value="${kind}">${cloud.me?selectInput('community','发布到社区',cloud.communities.map(c=>[c.id,c.name])):''}${field('title',kind==='article'?'文章标题':'活动名称','text','maxlength="80"')}${field('date','日期','date')}${kind==='article'?'<input type="hidden" name="time" value="09:00"><input type="hidden" name="place" value="社区科普"><input type="hidden" name="limit" value="1">':field('time','活动时间','time')+field('place','活动地点','text','maxlength="100"')+field('limit','参与名额','number','min="1" max="500" value="25"')}${selectInput('type','分类',kind==='article'?[['健康科普','健康科普'],['防骗知识','防骗知识']]:[['文化兴趣','文化兴趣'],['健康科普','健康科普'],['邻里交流','邻里交流']])}${textArea('desc',kind==='article'?'文章正文':'活动介绍')}<label class="form-group"><span>上传图片（可选，最多5MB）</span><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label>`,'确认发布'))}
