jobsPage=()=>heading('银发就业与志愿服务','浏览岗位方向，登记参与意向。')+note('以下为岗位方向样例，尚未接入真实招聘单位；不表示已有空缺，不收取报名费用。')+`<div class="tabs">${['全部','技能教学','社区互助','灵活岗位','兴趣创作'].map(t=>action('filter',t,filter===t?'selected':'',`data-value="${t}"`)).join('')}</div>`+jobCatalog.filter(j=>filter==='全部'||filter===j.cat).map(j=>`<button class="card request-card" data-action="x-go" data-page="job" data-id="${j.id}"><span class="badge">${j.cat}</span><h3>${j.title}</h3><p>${j.desc}</p><span class="text-btn">岗位介绍 ›</span></button>`).join('')+linkButton('applications','我的岗位意向','secondary');
function jobPage(){const j=jobCatalog.find(j=>j.id===selected)||jobCatalog[0];return heading(j.title,j.cat)+`<div class="card"><h3>岗位内容</h3><p>${j.desc}</p><h3>参与要求</h3><p>${j.requirements}</p><h3>地点与报酬</h3><p>${j.place} · 时间与报酬以真实发布方说明为准；当前无招聘承诺。</p></div>${command('read-job','听一听岗位介绍','secondary')}${newForm('job',field('name','称呼','text',`value="${esc(state.profile)}" maxlength="30"`)+textArea('skills','您的经验 / 参与意愿')+selectInput('availability','方便参与的时间',[['工作日上午','工作日上午'],['工作日下午','工作日下午'],['灵活协商','灵活协商']]),'保存岗位意向')}${note('本次意向保存到个人记录；如需社区协助，请通过找服务发起“银龄志愿服务”申请。')}`}
function applicationsPage(){return heading('我的岗位意向','已保存的参与方向')+(state.jobApplications.length?state.jobApplications.slice().reverse().map(a=>`<div class="card"><span class="badge">意向登记</span><h3>${esc(a.title)}</h3><p>${esc(a.skills)}</p><p>${esc(a.date)} · ${esc(a.availability)}</p>${command('withdraw-job','撤回意向','text-btn',`data-id="${a.id}"`)}</div>`).join(''):empty('还没有保存岗位意向。','briefcase'))+linkButton('jobs','浏览岗位方向','secondary')}
const lifeArticles=[
['l1','生命教育','和家人聊一聊照护愿望','从自己希望的生活方式谈起，沟通在意的事情和需要的帮助。涉及医疗、法律事务时，向相应专业人员咨询。'],['l2','家属支持','怎样倾听长辈的担忧','给对方完整表达的时间。询问需要哪一种帮助，定期沟通，遇到长期困扰时联系专业支持。'],['l3','安宁疗护','了解专业舒适照护','安宁疗护由专业团队评估和实施，关注症状缓解、生活质量、心理支持与个人尊严。具体适用情况请咨询医疗团队。'],['l4','科学观念','警惕“消灾治病”收费骗局','遇到以恐吓、保平安或包治病为由索要钱财的情况，先停止付款，与家属核实。身体不适应寻求正规医疗帮助。'],['l5','科学观念','让居家环境更安全','关注照明、防滑、通道与通风，减少绊倒风险。家具摆放优先考虑实际安全和使用方便。'],['l6','文明殡葬','提前了解正规殡葬服务','可向当地民政部门、正规殡葬机构核实办理流程和收费。具体政策因地区而异，勿向不明中介支付定金。'],['l7','文明殡葬','认识生态安葬','树葬、花葬、海葬等形式的办理条件因地区和机构而异。尊重本人及家庭意愿，通过当地正规机构了解。'],['l8','文明祭扫','用合适的方式寄托思念','鲜花、清扫、追忆和家庭纪念都可以表达思念。遵守场所管理要求，注意用火安全与环境保护。'],['l9','生命教育','记录属于自己的生活故事','选择一段想与家人分享的经历，用文字、照片或录音保存。是否分享及向谁分享，由本人决定。'],['l10','家属支持','照护者也需要休息','把照护任务适当分工，保留休息时间，向社区咨询可用支持。长期压力影响生活时可寻求专业帮助。']
].map(([id,cat,title,text])=>({id,cat,title,text}));
lifePage=()=>heading('生命教育与关怀','科学观念、文明新风与家庭支持')+`<div class="tabs">${['全部','生命教育','科学观念','文明殡葬','安宁疗护','文明祭扫','家属支持'].map(t=>action('filter',t,filter===t?'selected':'',`data-value="${t}"`)).join('')}</div>`+lifeArticles.filter(a=>filter==='全部'||a.cat===filter).map(a=>`<button class="card request-card" data-action="x-go" data-page="lifearticle" data-id="${a.id}"><span class="badge">${a.cat}</span><h3>${a.title}</h3><p>${a.text.slice(0,46)}…</p></button>`).join('')+action('service','咨询陪伴与关怀服务','primary','data-id="r5"');
function lifeArticlePage(){const a=lifeArticles.find(a=>a.id===selected)||lifeArticles[0];return heading(a.title,a.cat)+command('read-life','听一听','secondary')+`<div class="article"><p>${a.text}</p></div>`+linkButton('inbox','给社区留个言','secondary')}
const scienceData=[['s1','健康科普','记录血压时注意什么','按测量设备说明和医护人员指导使用。记录时间、数值与测量时状态，复测与异常处理请咨询医生。'],['s2','健康科普','居家防跌倒小提醒','保持通道通畅，浴室注意防滑，起夜保证照明。起身时放慢动作，必要时使用合适的辅助工具。'],['s3','健康科普','就诊前准备哪些资料','带好身份证、医保凭证、既往病历、检查报告及常用药清单，提前记下最想咨询的问题。'],['s4','防骗知识','验证码不能交给别人','无论对方自称何种身份，都不要透露银行卡密码和短信验证码。转账前用原有可靠渠道核实。'],['s5','健康科普','怎样整理用药清单','把药品名称、医嘱剂量和时间逐项写清楚，复诊时带给医生或药师核对。不要根据本平台示例增减药物。'],['s6','防骗知识','免费活动中的收费陷阱','对以免费礼品吸引、随后要求押金或高价购买的安排保持谨慎。付款前先与家属沟通，核实发布主体。']].map(([id,type,title,desc])=>({id,type,title,desc}));
function sciencePage(){const items=[...cloud.activities.filter(a=>a.kind==='article'),...state.customActivities.filter(a=>a.kind==='article'),...scienceData];return heading('健康科普文章库','阅读实用知识，社区可发布新文章。')+(state.role==='community'?command('science-publish','发布科普文章','primary'):'')+items.map(a=>`<button class="card request-card" data-action="x-go" data-page="sciencearticle" data-id="${a.id}"><span class="badge">${esc(a.type)}</span><h3>${esc(a.title)}</h3><p>${esc(a.desc.slice(0,70))}</p></button>`).join('')}
function scienceArticlePage(){const a=[...cloud.activities.filter(a=>a.kind==='article'),...state.customActivities.filter(a=>a.kind==='article'),...scienceData].find(a=>a.id===selected)||scienceData[0];return heading(esc(a.title),esc(a.communityName||'基础知识'))+command('read-science','听一听','secondary')+`<div class="article"><p>${esc(a.desc).replaceAll('\n','<br>')}</p></div>`}
function consultV2(){return heading('在线问诊与预约','科室方向、就医协助与就诊安排。')+note('未接入医院号源，无法完成真实挂号或医生问诊。以下可保存预约意向，并发起社区就医协助。')+[['全科','不确定从哪一科开始'],['心血管内科','已有相关诊断的随访安排'],['内分泌科','已有糖尿病等诊断的随访安排'],['神经内科','神经系统相关就诊咨询'],['呼吸内科','呼吸系统相关就诊咨询'],['骨科 / 康复科','骨关节或康复相关咨询']].map(([name,desc])=>`<div class="card"><h3>${name}</h3><p>${desc}</p>${command('appointment','保存预约意向','text-btn',`data-dept="${name}"`)}</div>`).join('')+action('service','申请社区就医协助','primary','data-id="r1"')+linkButton('appointments','查看我的就医安排','secondary')}
consultPage=consultV2;
function appointmentsPage(){return heading('我的就医安排','个人预约意向；请以医院实际确认结果为准。')+(state.appointments.length?state.appointments.map(a=>`<div class="card"><span class="badge">${a.confirmed?'已自行确认':'待自行联系医院'}</span><h3>${esc(a.dept)}</h3><p>${esc(a.hospital)}<br>${esc(a.date)} ${esc(a.time)}</p><p>${esc(a.note)}</p>${!a.confirmed?command('confirm-appointment','我已向医院确认','secondary',`data-id="${a.id}"`):''}${command('cancel-appointment','取消安排','text-btn',`data-id="${a.id}"`)}</div>`).join(''):empty('暂无就医安排。','doctor'))+linkButton('consult','查看科室与就医协助','secondary')}
const questionSet=[['健康需要','是否需要健康咨询或就医协助？','医','r1'],['生活照料','是否需要助餐或日常照料？','养','r2'],['学习兴趣','是否希望学习手机或兴趣课程？','学','r3'],['社会参与','是否想参与志愿服务或发挥专长？','用','r4'],['陪伴支持','是否需要倾听、家属支持或生命关怀？','安','r5']];
function intakePage(){return heading('五维需求评估','五个问题，帮助您选择服务方向。')+newForm('intake',questionSet.map(([title,q,dim],i)=>selectInput('q'+i,q,[['0','目前不需要'],['1','可以了解'],['2','比较需要']])).join(''),'查看匹配结果')+(state.intake?`<div class="card"><h3>上次评估</h3><p>核心需要：${esc(state.intake.primary.join('、')||'暂未选择')}</p><p>可以了解：${esc(state.intake.secondary.join('、')||'暂无')}</p></div>`:'')}
function intakeResultPage(){const r=state.intake;if(!r)return intakePage();return heading('服务匹配结果','根据您的选择生成，可随时重新评估。')+questionSet.map(([title,q,dim,rid],i)=>`<div class="need-dimension"><strong>${dim} · ${title}</strong><span class="dimension-track"><i style="width:${r.scores[i]/2*100}%"></i></span><small>${r.scores[i]===2?'核心需要':r.scores[i]===1?'次要需要':'暂不需要'}</small></div>`).join('')+questionSet.filter((x,i)=>r.scores[i]>0).sort((a,b)=>r.scores[questionSet.indexOf(b)]-r.scores[questionSet.indexOf(a)]).map(([title,q,dim,rid])=>`<div class="card"><h3>${title}</h3>${action('service','查看对应服务并申请','secondary',`data-id="${rid}"`)}</div>`).join('')+linkButton('ask','还有其他需要？和小花说一说','secondary')+linkButton('intake','重新评估','text-btn')}
const oldAsk=askPage;askPage=()=>heading('小花 · 服务助手','支持文字或语音输入，帮助找到服务方向。')+`<div class="demo-banner">当前使用五维关键词匹配；大模型与方言理解尚未接入。不进行医疗诊断。</div><div id="chat-log">${chatHistory.map(m=>`<div class="bubble ${m.me?'me':''}">${esc(m.text)}${m.resources?m.resources.map(id=>`<br>${action('service','查看'+resourceData.find(r=>r.id===id).title,'text-btn',`data-id="${id}"`)}`).join(''):''}</div>`).join('')||'<div class="bubble">您好，我是小花。可以告诉我“一个人住，想找人聊聊”，也可以先做五维需求评估。</div>'}</div>${command('recognize','点击说出您的需要','secondary','data-target="ask"')}<form id="x-chat" class="chat-form"><input name="question" aria-label="您的需要" placeholder="说说您的需要……" required maxlength="500"><button type="submit">发送</button></form>${command('read-chat','听一听回复','secondary')}${linkButton('intake','五道题，了解我的需要','text-btn')}`;
ask=function(q){q=q.trim();if(!q)return;const ids=[];if(/疼|痛|病|药|医院|血压|血糖|睡不|看病|就医/.test(q))ids.push('r1');if(/独居|一个人住|吃饭|助餐|照料|做饭/.test(q))ids.push('r2');if(/手机|学习|书法|课程|学会/.test(q))ids.push('r3');if(/工作|志愿|手艺|就业|帮忙/.test(q))ids.push('r4');if(/陪|聊|孤独|难过|一个人|心情|照护/.test(q))ids.push('r5');if(!ids.length)ids.push('r1','r2','r3','r4','r5');chatHistory.push({me:true,text:q},{text:'根据您提到的情况，建议先了解以下服务。进入服务介绍后，可以向您选择的社区发起申请。具体能否承接，由服务方确认。',resources:ids});render(true)};
function inboxPage(){const linked=cloud.me?[...cloud.linked.map(l=>[l.elder,l.name]),...cloud.familyUsers.filter(f=>f.granted).map(f=>[f.family,f.name])]:[];let list=cloud.me?cloud.messages:state.messages;return heading('家人与社区留言','支持文字、语音和回复。')+(cloud.me?selectInput('messageTarget','收件人',linked.length?linked:[['','暂无已连接家人']]):note('访客留言保存在本机；登录并连接家人后可发送。'))+newForm('message',textArea('text','写下您想说的话',false)+(cloud.me?optionalField('communityCode','或者发给社区（填写服务码）','text','maxlength="50"'):'')+`<div class="voice-controls">${command('record-voice','录一段语音','secondary')}${command('stop-voice','结束录音','text-btn')}<div id="voice-preview" role="status"></div></div>`,'保存 / 发送留言')+section('留言记录')+(list.length?list.slice().sort((a,b)=>(b.created||0)-(a.created||0)).map(m=>{let body;try{body=m.body?JSON.parse(m.body):{text:m.text||'',audio:m.audio||''}}catch{body={text:m.text||''}}return `<div class="card"><div class="row between"><h3>${esc(m.sender_name|| (m.role==='family'?'家属':'长者'))}</h3><small class="meta">${esc(m.date||new Date(m.created).toLocaleDateString('zh-CN'))}</small></div>${body.text?`<p>${esc(body.text)}</p>`:''}${body.audio?`<audio controls preload="none" src="${esc(body.audio)}"></audio>`:''}${m.reply?`<div class="reply-box"><strong>回复</strong><p>${esc(m.reply)}</p></div>`:''}${(cloud.me?(m.recipient===cloud.me.id||cloud.communities.some(c=>c.id===m.community)):state.role==='community')?command('reply','回复留言','text-btn',`data-id="${m.id}"`):''}</div>`}).join(''):empty('暂无留言。','mail'))}
