const oldPetPage=petPage;petPage=()=>{let html=oldPetPage();let leaves=Math.min(5,Math.floor(state.xp/100));return html.replace('<div class="pet-scene">',`<div class="pet-scene animated-pet"><div class="growth-leaves" aria-label="新增${leaves}片成长叶">${Array.from({length:leaves},(_,i)=>`<svg style="--leaf:${i}" viewBox="0 0 30 48" aria-hidden="true"><path d="M15 47C-6 30 0 9 29 1C30 28 23 40 15 47Z" fill="${i%2?'#849c5e':'#617f43'}"/><path d="M15 43 23 13" fill="none" stroke="#e4eaca" stroke-width="1.5"/></svg>`).join('')}</div>`)+`<div class="card"><h3>成长与成就</h3><p>每累计100成长值升一级，并增加一片成长叶（最多展示五片）。</p><div class="achievement-grid">${[['第一次记录',state.records.length>0],['学习起步',Object.keys(state.tasks).some(k=>k.startsWith('course-'))],['社区参与',state.joined.length>0],['展叶伙伴',level()>1]].map(([t,yes])=>`<span class="achievement ${yes?'earned':''}">${yes?'✓':'○'} ${t}</span>`).join('')}</div></div>${command('checkin',todaysTasks().includes('checkin')?'今天已打卡 ✓':'今日陪伴打卡 · +5','secondary')}${command('pet-command','对小颐说句话','secondary')}${note('形象来自项目PPT。当前支持轻动画、任务成长和设备语音；复杂表情动画与方言对话尚未接入。')}`};
const oldSettings=settingsPage;settingsPage=()=>oldSettings()+`<div class="card"><h3>设备可用播报语音</h3><p>只列出本设备实际提供的中文语音；未安装方言语音时不模拟方言。</p><select id="voice-select" aria-label="选择播报语音">${availableVoices().length?availableVoices().map(v=>`<option value="${esc(v.name)}" ${state.voiceName===v.name?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join(''):'<option>系统默认中文</option>'}</select></div>`;
function availableVoices(){return window.speechSynthesis?speechSynthesis.getVoices().filter(v=>/^(zh|yue|cmn)/i.test(v.lang)):[]}
speak=function(text){if(!state.voice)return toast('请先开启语音播报');if(!window.speechSynthesis)return toast('当前设备不支持语音播报');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);const v=availableVoices().find(v=>v.name===state.voiceName);if(v)u.voice=v;u.lang=v?.lang||'zh-CN';u.rate=.86;u.onerror=()=>toast('播报暂不可用，请查看文字');speechSynthesis.speak(u)};
function recognize(target){const S=window.SpeechRecognition||window.webkitSpeechRecognition;if(!S){toast('此浏览器不支持语音识别，请用文字输入；语音留言可单独录制。');return}const rec=new S();rec.lang='zh-CN';rec.interimResults=false;rec.onstart=()=>toast('正在听，请说话……');rec.onerror=e=>toast(e.error==='not-allowed'?'未获得麦克风权限，请使用文字输入。':'未能识别，请重试或输入文字。');rec.onresult=e=>{const t=e.results[0][0].transcript;if(target==='ask')ask(t);else if(/吃药|用药/.test(t))go('meds');else if(/活动/.test(t))go('activities');else if(/健康|记录/.test(t))go('health');else if(/学/.test(t))go('learning');else if(/家人|留言/.test(t))go('inbox');else speak('我听见了。您可以说，记录健康、查看活动、去学习或者给家人留言。')};rec.start()}
async function startAudio(){if(voiceRecorder?.state==='recording')return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('当前设备不支持录音，请使用文字留言');return}try{voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});voiceChunks=[];pendingAudio='';const mime=['audio/webm','audio/mp4','audio/ogg'].find(t=>MediaRecorder.isTypeSupported(t));voiceRecorder=new MediaRecorder(voiceStream,mime?{mimeType:mime}:undefined);voiceRecorder.ondataavailable=e=>{if(e.data.size)voiceChunks.push(e.data)};voiceRecorder.onstop=async()=>{clearTimeout(recordLimit);voiceStream.getTracks().forEach(t=>t.stop());const blob=new Blob(voiceChunks,{type:voiceRecorder.mimeType});if(blob.size>5*1024*1024){toast('录音太大，请缩短后重试');return}const reader=new FileReader();reader.onload=()=>{pendingAudio=reader.result;const view=$('#voice-preview');if(view)view.innerHTML='<p>语音已录制，请试听后发送。</p><audio controls src="'+pendingAudio+'"></audio>'};reader.readAsDataURL(blob)};voiceRecorder.start();recordStarted=Date.now();recordLimit=setTimeout(()=>{if(voiceRecorder?.state==='recording')voiceRecorder.stop()},60000);$('#voice-preview').textContent='录音中，最多60秒；点“结束录音”后试听。'}catch{toast('未能获得麦克风权限，请使用文字留言')}}
async function uploadFile(file,isPublic=false){if(file.size>5*1024*1024)throw new Error('文件不能超过5MB');if(!cloud.me){if(file.size>1500000)throw new Error('访客本机文件请小于1.5MB；登录后支持5MB');return new Promise((ok,bad)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=bad;r.readAsDataURL(file)})}const r=await fetch('/api/upload?public='+(isPublic?'1':'0'),{method:'POST',headers:{'Content-Type':file.type},body:file});const d=await r.json();if(!r.ok)throw new Error(d.error||'上传失败');return d.url}
function stopAudio(){if(voiceRecorder?.state==='recording')voiceRecorder.stop()}
const oldGo=go;go=function(p,id){if(voiceRecorder?.state==='recording')stopAudio();if(p==='health'&&state.role==='family'&&cloud.me){history.push(page);page=p;closeModal();render();location.hash=p;return}oldGo(p,id)};
