const accountWithRecovery=accountPage;accountPage=()=>accountWithRecovery()+(cloud.me?`<div class="card"><h3>同步冲突恢复</h3><p>另一设备改动记录时，先保留本机副本，再加载云端版本。待合并副本始终留在此浏览器。</p>${command('recover-cloud','保留副本并加载云端','secondary')}${command('merge-pending','合并待同步副本','secondary')}</div>`:'');window.extraViews.account=accountPage;
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||!['x-recover-cloud','x-merge-pending'].includes(b.dataset.action))return;e.preventDefault();e.stopImmediatePropagation();try{if(b.dataset.action==='x-recover-cloud'){if(cloud.busy)throw new Error('正在同步，请稍后');localStorage.setItem('yilu-pending-'+cloud.me.id,JSON.stringify(snapshot()));cloud.dirty=false;clearTimeout(cloud.saveTimer);await refreshCloud();toast('本机副本已保留，云端版本已加载')}else{const raw=JSON.parse(localStorage.getItem('yilu-pending-'+cloud.me.id)||'null');if(!raw)throw new Error('没有待合并副本');const saved=sanitizeBackup(raw);for(const k of ['records','medications','requests','messages','appointments','jobApplications','contacts','joined','meds'])state[k]=[...new Map([...(state[k]||[]),...(saved[k]||[])].map(x=>[typeof x==='object'?(x.id||JSON.stringify(x)):x,x])).values()];persist();await saveCloud();if(!cloud.dirty)localStorage.removeItem('yilu-pending-'+cloud.me.id);render();toast(cloud.dirty?'已合并到本机，云端同步待重试':'待同步副本已合并')}}catch(err){toast(err.message)}},true);
