let modalReturnFocus=null;
const basicModal=modal;modal=function(title,body){modalReturnFocus=document.activeElement;basicModal(title,body);requestAnimationFrame(()=>$('#modal-root input, #modal-root textarea, #modal-root button')?.focus())};
const basicCloseModal=closeModal;closeModal=function(){basicCloseModal();if(modalReturnFocus?.isConnected)modalReturnFocus.focus();modalReturnFocus=null};
document.addEventListener('keydown',e=>{const root=$('#modal-root');if(!root?.children.length)return;if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const all=[...root.querySelectorAll('button,a[href],input,select,textarea')].filter(el=>!el.disabled&&el.offsetParent!==null);if(!all.length)return;const first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
